(()=>{
 const V=window.Views,M=window.Studio,P=window.PatternTexture;
 const slider=(label,key,val,min,max,suffix='')=>`<label class="range-field"><span>${label}<output data-output="${key}">${val}${suffix}</output></span><input type="range" data-field="${key}" aria-label="${label}" min="${min}" max="${max}" value="${val}"></label>`;
 const oldTools=V.tools;
 V.tools=c=>{const d=c.d;if(c.tool==='layout')return `<div class="pattern-layouts">${[['single','单幅'],['repeat','重复'],['brick','错位'],['mirror','镜像'],['wrap','环绕']].map(([key,label])=>V.btn(label,'pattern-layout','',`data-id="${key}" aria-pressed="${d.patternLayout===key}"`)).join('')}</div><div class="pattern-flips">${V.btn('水平翻转','pattern-flip','secondary',`data-id="flipX" aria-pressed="${!!d.flipX}"`)}${V.btn('垂直翻转','pattern-flip','secondary',`data-id="flipY" aria-pressed="${!!d.flipY}"`)}</div>${d.patternLayout!=='single'?`<div class="range-grid">${slider('重复密度','repeatDensity',d.repeatDensity??4,2,8)}${slider('单元留白','repeatGap',d.repeatGap??12,0,60,'%')}</div>`:''}<div class="range-grid">${slider('可见宽度' ,'cropWidth',d.cropWidth,20,100,'%')}${slider('可见高度','cropHeight',d.cropHeight,20,100,'%')}</div><p class="tool-help">从同一素材试不同组合。镜像会翻转文字；环绕为环形构图。导出为当前画布，不承诺无缝拼接。</p>`;
 if(c.tool==='material')return `<span class="tool-label">${window.EditorObject.enabled(d)?'器物釉色':'画布底色'}</span><div class="swatches">${window.Art.palette.map(p=>`<button data-action="${window.EditorObject.enabled(d)?'editor-glaze':'color'}" data-id="${p.id}" aria-pressed="${(window.EditorObject.enabled(d)?d.cupMaterial.color:d.color)===p.id}" style="--swatch:${p.color}"><i></i>${p.name}</button>`).join('')}</div>`;
 return oldTools(c);};
 V.editor=c=>{const d=c.d;if(!d)return V.empty('没有正在编辑的草稿','从共创或我的中继续。');return `<section class="editor-screen pattern-editor"><div class="pattern-source">来源 · ${V.esc(M.heritageObjects.find(o=>o.id===d.sourceObjectId)?.name||'项目示意')}<span>${window.EditorObject.enabled(d)?'目标 · '+window.Vessels.get(d.canvas).name:'二维纹样 / 1:1'}</span></div><div class="editor-meta">${window.EditorObject.switcher(d)||'<span>示意素材 · 本机草稿</span>'}<div>${V.ib('undo','undo','撤销',d.past.length?'':'disabled')}${V.ib('redo','redo','重做',d.future.length?'':'disabled')}${V.ib('rotate','reset','重置编辑参数')}</div></div>${window.EditorObject.enabled(d)?window.EditorObject.stage(d):`<div class="canvas-stage pattern-stage"><div id="work-preview">${P.svg(d,{guides:true})}</div><span class="canvas-note">拖动纹样 · 虚线为可见边界</span></div>`}<div class="pattern-version-bar">${V.btn(`关键版本 · ${d.versions.length}`,'versions','text')}${V.btn('导出贴图','texture-export','text')}</div><div class="editor-tools"><div class="tool-tabs" role="tablist" aria-label="编辑工具">${[['compose','构图'],['layout','排布'],['material','配色'],['motif','素材']].map(([id,name])=>`<button role="tab" data-action="tool" data-id="${id}" aria-selected="${c.tool===id}">${name}</button>`).join('')}</div><div class="tool-panel" role="tabpanel">${V.tools(c)}</div></div><div class="editor-footer">${V.btn(d.category==='enamel'?'全屏预览':'此类别3D待接入','cup-open','secondary',d.category==='enamel'?'':'disabled')}${V.btn('保存作品','finish','primary')}</div></section>`;};
 V.versions=d=>`<p>保存当前参数与素材引用；切换版本也可撤销。不增加积分。</p><label class="field"><span>版本名称</span><input id="version-name" class="input" maxlength="24" placeholder="例如：蓝白环绕"></label>${V.btn('保存当前为关键版本','version-save','primary full')}<div class="version-list">${d.versions.length?d.versions.slice().reverse().map(v=>`<article><div><strong>${V.esc(v.name)}</strong><small>${V.date(v.createdAt)} · ${V.esc({single:'单幅',repeat:'重复',wrap:'环绕',brick:'错位',mirror:'镜像'}[v.snapshot.patternLayout]||'单幅')}</small></div>${V.btn('切换','version-restore','secondary',`data-id="${v.id}"`)}${V.ib('trash','version-delete','删除版本'+V.esc(v.name),`data-id="${v.id}"`)}</article>`).join(''):'<p class="search-empty">暂无关键版本。先保留一个喜欢的状态。</p>'}</div>`;
})();
